                    "url"
                  ],
                  "type": "object"
                },
                "type": "array"
              },
              "units": {
                "minLength": 1,
                "type": "string"
              },
              "value": {
                "minLength": 1,
                "type": "string"
              }
            },
            "required": [
              "value"
