          },
          "minItems": 1,
          "type": "array"
        }
      },
      "properties": {},
      "type": "object"
    },
    "description": {
      "description": "More extensive free-form description.",
      "minLength": 1,
      "type": "string"
    },
    "releaseDate": {
      "_format": "date",
      "type": "string"
    },
    "sampleRelationships": {
      "items": {
        "oneOf": [
          {
            "required": [
              "alias",
              "team",
              "nature"
            ]
          },
          {
            "required": [
              "accession",
              "nature"
            ]
          }
        ],
        "properties": {
          "accession": {
            "minLength": 1,
            "type": "string"
