              "recurated from"
            ],
            "type": "string"
          },
          "team": {
            "minLength": 1,
            "type": "string"
          }
        },
        "type": "object"
      },
      "type": "array"
    },
    "taxonomy": {
      "properties": {
        "taxonId": {
          "type": "integer"
        },
        "taxonName": {
          "minLength": 1,
          "type": "string"
        }
      },
      "required": [
        "taxonId"
      ],
      "type": "object"
    },
    "title": {
      "description": "Title of the sample.",
      "minLength": 1,
      "type": "string"
    }
  },
  "required": [
    "alias",
    "taxonomy",
    "releaseDate"
  ],
